USE ROLE EDP_ENGINEER;
USE DATABASE ENTERPRISE_DATA;
USE SCHEMA RAW;
CREATE TABLE IF NOT EXISTS VEHICLE_EVENTS (EVENT_ID STRING, EVENT_TS TIMESTAMP_NTZ, VIN STRING, CUSTOMER_ID STRING, MARKET STRING, EVENT_TYPE STRING, SOFTWARE_VERSION STRING, BATTERY_SOC NUMBER(5,2), BATTERY_HEALTH NUMBER(5,2), ODOMETER_KM NUMBER(12,2), LATITUDE FLOAT, LONGITUDE FLOAT, SPEED_KPH NUMBER(6,2), DTC_CODE STRING, OTA_CAMPAIGN_ID STRING, PAYLOAD VARIANT, INGESTED_AT TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP());
CREATE TABLE IF NOT EXISTS CUSTOMERS (CUSTOMER_ID STRING, MARKET STRING, CITY STRING, AGE_BAND STRING, INCOME_BAND STRING, CURRENT_BRAND STRING, NEXT_BRAND STRING, PREFERRED_POWERTRAIN STRING, CONSENT_MARKETING BOOLEAN, CONSENT_CONNECTED_DATA BOOLEAN, EMAIL STRING, PHONE STRING, SOURCE_PAYLOAD VARIANT, INGESTED_AT TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP());
CREATE TABLE IF NOT EXISTS VEHICLES (VIN STRING, CUSTOMER_ID STRING, MODEL STRING, MODEL_YEAR NUMBER, POWERTRAIN STRING, SALE_DATE DATE, CONNECTED BOOLEAN, SOFTWARE_VERSION STRING, WARRANTY_END_DATE DATE, MARKET STRING, INGESTED_AT TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP());
CREATE TABLE IF NOT EXISTS SALES_ORDERS (ORDER_ID STRING, CUSTOMER_ID STRING, VIN STRING, ORDER_TS TIMESTAMP_NTZ, CHANNEL STRING, DEALER_ID STRING, MODEL STRING, POWERTRAIN STRING, LIST_PRICE NUMBER(14,2), DISCOUNT NUMBER(14,2), NET_PRICE NUMBER(14,2), STATUS STRING, MARKET STRING, INGESTED_AT TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP());
CREATE TABLE IF NOT EXISTS CAMPAIGN_EVENTS (EVENT_ID STRING, CUSTOMER_ID STRING, EVENT_TS TIMESTAMP_NTZ, CAMPAIGN_ID STRING, CHANNEL STRING, ACTION STRING, COST NUMBER(14,4), ATTRIBUTED_REVENUE NUMBER(14,2), MARKET STRING, INGESTED_AT TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP());
CREATE TABLE IF NOT EXISTS SUPPORT_TICKETS (TICKET_ID STRING, CUSTOMER_ID STRING, VIN STRING, CREATED_TS TIMESTAMP_NTZ, CLOSED_TS TIMESTAMP_NTZ, CATEGORY STRING, SEVERITY STRING, CHANNEL STRING, SLA_MINUTES NUMBER, FIRST_CONTACT_RESOLVED BOOLEAN, CSAT NUMBER(4,2), MARKET STRING, INGESTED_AT TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP());
CREATE TABLE IF NOT EXISTS FINANCIAL_TRANSACTIONS (TXN_ID STRING, TXN_TS TIMESTAMP_NTZ, CUSTOMER_ID STRING, VIN STRING, TXN_TYPE STRING, REVENUE NUMBER(14,2), COST NUMBER(14,2), CURRENCY STRING, MARKET STRING, INGESTED_AT TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP());
CREATE TABLE IF NOT EXISTS OTA_DEPLOYMENTS (DEPLOYMENT_ID STRING, VIN STRING, CAMPAIGN_ID STRING, START_TS TIMESTAMP_NTZ, END_TS TIMESTAMP_NTZ, FROM_VERSION STRING, TO_VERSION STRING, STATUS STRING, ROLLBACK BOOLEAN, ERROR_CODE STRING, MARKET STRING, INGESTED_AT TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP());
